    def get_contrasting_text_color(self, background_color_hex, wcag_threshold=4.5):
        """
        Selects a text color from the theme that provides the best contrast against a given background.
        It prioritizes the main text_color but falls back to text_color_inverted if contrast is poor.

        Args:
            background_color_hex (str): The background color in hex format (e.g., '#RRGGBB').
            wcag_threshold (float): The minimum acceptable WCAG contrast ratio.
                                    (e.g., 4.5 for AA level for small text).
        
        Returns:
            str: The hex color code of the text color with sufficient contrast,
                 or the primary text color if inverted text color is not available.
        """
        primary_text_color = self.colors.get('text_color', '#000000')
        inverted_text_color = self.colors.get('text_color_inverted', None)

        # Always check primary text color first
        contrast_primary = BasePlotter._get_contrast_ratio_wcag(primary_text_color, background_color_hex)
        
        if contrast_primary >= wcag_threshold:
            return primary_text_color
        elif inverted_text_color:
            # If primary text color fails, check inverted if available
            contrast_inverted = BasePlotter._get_contrast_ratio_wcag(inverted_text_color, background_color_hex)
            if contrast_inverted >= wcag_threshold:
                return inverted_text_color
            else:
                # If neither meets threshold, return the one with higher contrast
                # or just the primary as a fallback (whichever has better contrast)
                if contrast_inverted > contrast_primary:
                    return inverted_text_color
                else:
                    return primary_text_color
        else:
            # No inverted color, or both failed, return primary
            return primary_text_color

    @staticmethod
    def _hex_to_luminance(hex_color):
        """Calculates relative luminance to sort colors by brightness."""
        import matplotlib.colors as mcolors
        rgb = mcolors.to_rgb(hex_color)
        # Standard formula for perceived brightness
        return 0.299 * rgb[0] + 0.587 * rgb[1] + 0.114 * rgb[2]

    def _generate_colormaps_from_palette(self):
        """
        Generates Sequential, Diverging, and Raw colormaps from the theme's 
        categorical color list and stores them in the instance.
        """
        import matplotlib.colors as mcolors

        category_list = self.colors.get('category_color_scale')
        if not category_list or not isinstance(category_list, list):
            # This should not happen due to the fallback in __init__, but as a safeguard:
            return 

        theme_name = self.theme

        # --- A. SEQUENTIAL ---
        sorted_colors = sorted(category_list, key=self._hex_to_luminance)
        self.sequential_cmap = mcolors.LinearSegmentedColormap.from_list(
            f"{theme_name}_sequential", sorted_colors, N=256
        )

        # --- B. DIVERGING ---
        if len(category_list) >= 2:
            color_start = category_list[0]
            color_end = category_list[1]
            
            if "light" in theme_name:
                neutral = self.colors.get('bg_color', '#f5f5f5')
            else:
                neutral = self.colors.get('bg_color', '#2b2b2b')
            
            self.diverging_cmap = mcolors.LinearSegmentedColormap.from_list(
                f"{theme_name}_diverging", [color_start, neutral, color_end], N=256
            )
        else:
            self.diverging_cmap = None

        # --- C. RAW (Spectral) ---
        self.raw_cmap = mcolors.LinearSegmentedColormap.from_list(
            f"{theme_name}_raw", category_list, N=256
        )

    def get_continuous_colormap(self, colors: Optional[List[str]] = None, name: str = "custom_theme_map"):
        """
        Generates a continuous colormap from a list of theme colors.

        Args:
            colors (list, optional): A list of hex colors to create a gradient from. 
                                     If None, a default gradient is created from the theme's 
                                     background color to its main theme color.
            name (str, optional): The name for the new colormap.

        Returns:
            A matplotlib.colors.LinearSegmentedColormap object.
        """
        from matplotlib.colors import LinearSegmentedColormap
        
        if colors is None:
            # Create a default sequential gradient
            colors = [self.colors['bg_color'], self.colors['theme_color']]
        
        return LinearSegmentedColormap.from_list(name, colors)

