# --- Global WCAG Helper Functions (moved from BasePlotter static methods) ---
def _hex_to_rgb_linear(hex_color):
    """Converts hex color to linear RGB components (0-1 range)."""
    hex_color = hex_color.lstrip('#')
    rgb_tuple = tuple(int(hex_color[i:i+2], 16) / 255.0 for i in (0, 2, 4))

    # Convert sRGB to linear RGB
    linear_rgb = []
    for c in rgb_tuple:
        if c <= 0.03928:
            linear_rgb.append(c / 12.92)
        else:
            linear_rgb.append(((c + 0.055) / 1.055) ** 2.4)
    return linear_rgb

def _get_relative_luminance_wcag(color_hex):
    """Calculates the relative luminance (WCAG) for a given hex color."""
    r_lin, g_lin, b_lin = _hex_to_rgb_linear(color_hex)
    return 0.2126 * r_lin + 0.7152 * g_lin + 0.0722 * b_lin

def _get_contrast_ratio_wcag(color1_hex, color2_hex):
    """Calculates the WCAG contrast ratio between two hex colors."""
    lum1 = _get_relative_luminance_wcag(color1_hex)
    lum2 = _get_relative_luminance_wcag(color2_hex)

    # L1 is the brighter of the two colors, L2 is the darker
    l_bright = max(lum1, lum2)
    l_dark = min(lum1, lum2)

    return (l_bright + 0.05) / (l_dark + 0.05)


# --- Master Plot Class (Plotter) ---
class BasePlotter:
    """Base class for plotting, providing shared settings and functionality."""

    _ALL_THEMES = {} # Will be populated from JSON

    @staticmethod
    def _load_themes_from_file(filepath):
        if not os.path.exists(filepath):
            print(f"Warning: Theme file not found at {filepath}")
            return {}
        try:
            with open(filepath, 'r') as f:
                themes = json.load(f)
            return themes
        except json.JSONDecodeError:
            print(f"Error: Could not decode JSON from {filepath}")
            return {}
        except Exception as e:
            print(f"An unexpected error occurred while loading themes from {filepath}: {e}")
            return {}

    # Load all themes from the themes directory
    _THEMES_DIR = os.path.join(os.path.dirname(__file__), 'themes')
    if os.path.isdir(_THEMES_DIR):
        for filename in sorted(os.listdir(_THEMES_DIR)): # sorted to have predictable override order
            if filename.endswith('.json'):
                filepath = os.path.join(_THEMES_DIR, filename)
                _ALL_THEMES.update(_load_themes_from_file(filepath))

    STYLE_PRESETS = {
        "matplotlib": {
